181	// classifySession determines if a session is stuck and returns diagnostic info.
182	// Returns nil if the session is healthy.
183	func classifySession(state *strategy.SessionState, repo *git.Repository, now time.Time) *stuckSession {
184		// Determine shadow branch info
185		shadowBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
186		refName := plumbing.NewBranchReferenceName(shadowBranch)
187		_, refErr := repo.Reference(refName, true)
188		hasShadowBranch := refErr == nil
189	
190		switch {
191		case state.Phase.IsActive():
192			if !state.IsStuckActive() {
193				return nil
194			}
195	
196			var reason string
197			if state.LastInteractionTime != nil {
198				reason = fmt.Sprintf("active, last interaction %s ago", now.Sub(*state.LastInteractionTime).Truncate(time.Minute))
199			} else {
200				reason = fmt.Sprintf("active, started %s ago with no recorded interaction", now.Sub(state.StartedAt).Truncate(time.Minute))
201			}
202	
203			return &stuckSession{
204				State:             state,
205				Reason:            reason,
206				ShadowBranch:      shadowBranch,
207				HasShadowBranch:   hasShadowBranch,
208				CheckpointCount:   state.StepCount,
209				FilesTouchedCount: len(state.FilesTouched),
210			}
211	
212		case state.Phase == session.PhaseEnded:
213			// Ended sessions are stuck if they have uncondensed data
214			if state.StepCount <= 0 || !hasShadowBranch {
215				return nil
216			}
217	
218			return &stuckSession{
219				State:             state,
220				Reason:            "ended with uncondensed checkpoint data",
221				ShadowBranch:      shadowBranch,
222				HasShadowBranch:   hasShadowBranch,
223				CheckpointCount:   state.StepCount,
224				FilesTouchedCount: len(state.FilesTouched),
225			}
226	
227		default:
228			return nil
229		}
230	}
231	
232	// displayStuckSession prints diagnostic info for a stuck session.
233	func displayStuckSession(cmd *cobra.Command, ss stuckSession) {
234		w := cmd.OutOrStdout()
235	
236		fmt.Fprintf(w, "  Session: %s\n", ss.State.SessionID)
237		fmt.Fprintf(w, "  Phase:   %s\n", ss.State.Phase)
238		fmt.Fprintf(w, "  Reason:  %s\n", ss.Reason)
239	
240		if ss.State.AgentType != "" {
241			fmt.Fprintf(w, "  Agent:   %s\n", ss.State.AgentType)
242		}
243	
244		if ss.State.LastInteractionTime != nil {
245			fmt.Fprintf(w, "  Last interaction: %s\n", ss.State.LastInteractionTime.Format(time.RFC3339))
246		}
247	
248		shadowStatus := "not found"
249		if ss.HasShadowBranch {
250			shadowStatus = fmt.Sprintf("exists (%s)", ss.ShadowBranch)
251		}
252		fmt.Fprintf(w, "  Shadow branch: %s\n", shadowStatus)
253		fmt.Fprintf(w, "  Checkpoints: %d, Files touched: %d\n", ss.CheckpointCount, ss.FilesTouchedCount)
254	}
255	
256	// promptSessionAction asks the user what to do with a stuck session.
257	func promptSessionAction(ss stuckSession) (string, error) {
258		var action string
259	
260		options := make([]huh.Option[string], 0, 3)
261		if ss.HasShadowBranch && ss.CheckpointCount > 0 {
262			options = append(options, huh.NewOption("Condense (save to permanent storage)", "condense"))
263		}
264		options = append(options,
265			huh.NewOption("Discard (remove session data)", "discard"),
266			huh.NewOption("Skip (leave as-is)", "skip"),
267		)
268	
269		form := NewAccessibleForm(
270			huh.NewGroup(
271				huh.NewSelect[string]().
272					Title(fmt.Sprintf("Fix session %s?", ss.State.SessionID)).
273					Options(options...).
274					Value(&action),
275			),
276		)
277	
278		if err := form.Run(); err != nil {
279			return "", fmt.Errorf("session fix prompt failed: %w", err)
280		}
281	
282		return action, nil
283	}
284	
285	// discardSession removes session state and cleans up the shadow branch.
286	func discardSession(ctx context.Context, ss stuckSession, _ *git.Repository, errW io.Writer) error {
287		// Clear session state file
288		if err := strategy.ClearSessionState(ctx, ss.State.SessionID); err != nil {
289			return fmt.Errorf("failed to clear session state: %w", err)
290		}
291	
292		// Delete shadow branch if it exists and no other sessions need it
293		if ss.HasShadowBranch {
294			if shouldDelete, err := canDeleteShadowBranch(ctx, ss.ShadowBranch, ss.State.SessionID); err != nil {
295				fmt.Fprintf(errW, "Warning: could not check other sessions for shadow branch: %v\n", err)
296			} else if shouldDelete {
297				if err := strategy.DeleteBranchCLI(ctx, ss.ShadowBranch); err != nil {
298					// Branch already gone is not an error — keeps discard idempotent
299					if !errors.Is(err, strategy.ErrBranchNotFound) {
300						return fmt.Errorf("failed to delete shadow branch: %w", err)
301					}
302				}
303			}
304		}
305	
306		return nil
307	}
308	
309	// checkDisconnectedMetadata detects and optionally repairs disconnected
310	// local/remote metadata branches (the "empty-orphan bug").
311	func checkDisconnectedMetadata(cmd *cobra.Command, force bool) error {
312		repo, err := openRepository(cmd.Context())
313		if err != nil {
314			return fmt.Errorf("failed to open repository: %w", err)
315		}
316	
317		ctx := cmd.Context()
318		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
319		disconnected, err := strategy.IsMetadataDisconnected(ctx, repo, remoteRefName)
320		if err != nil {
321			return fmt.Errorf("could not check metadata branch state: %w", err)
322		}
323	
324		w := cmd.OutOrStdout()
325	
326		if !disconnected {
327			fmt.Fprintln(w, "✓ Metadata branches: OK")
328			return nil
329		}
330	
331		fmt.Fprintln(w, "Metadata branches: DISCONNECTED")
332		fmt.Fprintln(w, "  Local and remote entire/checkpoints/v1 branches share no common ancestor.")
333		fmt.Fprintln(w, "  Some remote checkpoints may not be visible locally.")
334		fmt.Fprintln(w, "  Fix: cherry-pick local checkpoints onto remote tip (preserves all data).")
335	
336		if !force {
337			var confirmed bool
338			form := NewAccessibleForm(
339				huh.NewGroup(
340					huh.NewConfirm().
341						Title("Fix disconnected metadata branches?").
342						Value(&confirmed),
343				),
344			)
345			if formErr := form.Run(); formErr != nil {
346				if errors.Is(formErr, huh.ErrUserAborted) {
347					return nil
348				}
349				return fmt.Errorf("prompt failed: %w", formErr)
350			}
351			if !confirmed {
352				fmt.Fprintln(w, "  -> Skipped")
353				return nil
354			}
355		}
356	
357		if fixErr := strategy.ReconcileDisconnectedMetadataBranch(ctx, repo, remoteRefName, cmd.ErrOrStderr()); fixErr != nil {
358			return fmt.Errorf("failed to reconcile metadata branches: %w", fixErr)
359		}
360	
361		fmt.Fprintln(w, "  ✓ Fixed: metadata branches reconciled")
362		return nil
363	}
364	
365	// canDeleteShadowBranch checks if a shadow branch can be safely deleted.
366	// Returns true if no other sessions (besides excludeSessionID) need this branch.
367	func canDeleteShadowBranch(ctx context.Context, shadowBranch, excludeSessionID string) (bool, error) {
368		states, err := strategy.ListSessionStates(ctx)
369		if err != nil {
370			return false, fmt.Errorf("failed to list session states: %w", err)
371		}
372	
373		for _, state := range states {
374			if state.SessionID == excludeSessionID {
375				continue
376			}
377			otherShadow := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
378			if otherShadow == shadowBranch && state.StepCount > 0 {
379				return false, nil
380			}
381		}
382	
383		return true, nil
384	}
