22	)
23	
24	// ReadCommitted reads the checkpoint summary from the v2 /main ref.
25	// Returns nil, nil if the checkpoint doesn't exist (same contract as GitStore.ReadCommitted).
26	func (s *V2GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
27		if err := ctx.Err(); err != nil {
28			return nil, err //nolint:wrapcheck // Propagating context cancellation
29		}
30	
31		refName := plumbing.ReferenceName(paths.V2MainRefName)
32		_, rootTreeHash, err := s.GetRefState(refName)
33		if err != nil {
34			return nil, nil //nolint:nilnil,nilerr // Ref doesn't exist means no checkpoint
35		}
36	
37		rootTree, err := s.repo.TreeObject(rootTreeHash)
38		if err != nil {
39			return nil, nil //nolint:nilnil,nilerr // Tree not readable
40		}
41	
42		cpTree, err := rootTree.Tree(checkpointID.Path())
43		if err != nil {
44			return nil, nil //nolint:nilnil,nilerr // Checkpoint subtree not found
45		}
46	
47		metadataFile, err := cpTree.File(paths.MetadataFileName)
48		if err != nil {
49			return nil, nil //nolint:nilnil,nilerr // metadata.json not found
50		}
51	
52		content, err := metadataFile.Contents()
53		if err != nil {
54			return nil, fmt.Errorf("failed to read metadata.json: %w", err)
55		}
56	
57		var summary CheckpointSummary
58		if err := json.Unmarshal([]byte(content), &summary); err != nil {
59			return nil, fmt.Errorf("failed to parse metadata.json: %w", err)
60		}
61	
62		return &summary, nil
63	}
64	
65	// ListCommitted lists all committed checkpoints from the v2 /main ref.
66	// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
67	func (s *V2GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
68		if err := ctx.Err(); err != nil {
69			return nil, err //nolint:wrapcheck // Propagating context cancellation
70		}
71	
72		refName := plumbing.ReferenceName(paths.V2MainRefName)
73		_, rootTreeHash, err := s.GetRefState(refName)
74		if err != nil {
75			return []CommittedInfo{}, nil //nolint:nilerr // No /main ref means empty list
76		}
77	
78		rootTree, err := s.repo.TreeObject(rootTreeHash)
79		if err != nil {
80			return []CommittedInfo{}, nil //nolint:nilerr // Unreadable tree means no listable entries
81		}
82	
83		var checkpoints []CommittedInfo
84	
85		_ = WalkCheckpointShards(s.repo, rootTree, func(checkpointID id.CheckpointID, cpTreeHash plumbing.Hash) error { //nolint:errcheck // callback never returns errors
86			checkpointTree, cpTreeErr := s.repo.TreeObject(cpTreeHash)
87			if cpTreeErr != nil {
88				logging.Debug(ctx, "v2 ListCommitted: skipping unreadable checkpoint tree",
89					slog.String("checkpoint_id", checkpointID.String()),
90					slog.String("error", cpTreeErr.Error()))
91				return nil
92			}
93	
94			info := CommittedInfo{CheckpointID: checkpointID}
95	
96			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
97				if content, contentErr := metadataFile.Contents(); contentErr == nil {
98					var summary CheckpointSummary
99					if unmarshalErr := json.Unmarshal([]byte(content), &summary); unmarshalErr != nil {
100						logging.Debug(ctx, "v2 ListCommitted: skipping malformed metadata",
101							slog.String("checkpoint_id", checkpointID.String()),
102							slog.String("error", unmarshalErr.Error()))
103					} else {
104						info.CheckpointsCount = summary.CheckpointsCount
105						info.FilesTouched = summary.FilesTouched
106						info.SessionCount = len(summary.Sessions)
107	
108						if len(summary.Sessions) > 0 {
109							latestIndex := len(summary.Sessions) - 1
110							latestDir := strconv.Itoa(latestIndex)
111							if sessionTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
112								if sessionMetadataFile, smErr := sessionTree.File(paths.MetadataFileName); smErr == nil {
113									if sessionContent, scErr := sessionMetadataFile.Contents(); scErr == nil {
114										var sessionMetadata CommittedMetadata
115										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
116											info.Agent = sessionMetadata.Agent
117											info.SessionID = sessionMetadata.SessionID
118											info.CreatedAt = sessionMetadata.CreatedAt
119										}
120									}
121								}
122							}
123						}
124					}
125				}
126			}
127	
128			checkpoints = append(checkpoints, info)
129			return nil
130		})
131	
132		sort.Slice(checkpoints, func(i, j int) bool {
133			return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
134		})
135	
136		return checkpoints, nil
137	}
138	
139	// ReadSessionCompactTranscript reads transcript.jsonl for a session from the v2
140	// /main ref. Returns ErrNoTranscript when compact transcript is missing.
141	func (s *V2GitStore) ReadSessionCompactTranscript(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) ([]byte, error) {
142		if err := ctx.Err(); err != nil {
143			return nil, err //nolint:wrapcheck // Propagating context cancellation
144		}
145	
146		refName := plumbing.ReferenceName(paths.V2MainRefName)
147		_, rootTreeHash, err := s.GetRefState(refName)
148		if err != nil {
149			return nil, ErrCheckpointNotFound
150		}
151	
152		rootTree, err := s.repo.TreeObject(rootTreeHash)
153		if err != nil {
154			return nil, ErrCheckpointNotFound
155		}
156	
157		cpTree, err := rootTree.Tree(checkpointID.Path())
158		if err != nil {
159			return nil, ErrCheckpointNotFound
160		}
161	
162		sessionDir := strconv.Itoa(sessionIndex)
163		sessionTree, err := cpTree.Tree(sessionDir)
164		if err != nil {
165			return nil, ErrCheckpointNotFound
166		}
167	
168		compactFile, err := sessionTree.File(paths.CompactTranscriptFileName)
169		if err != nil {
170			return nil, ErrNoTranscript
171		}
172	
173		content, err := compactFile.Contents()
174		if err != nil {
175			return nil, ErrNoTranscript
176		}
177		if content == "" {
178			return nil, ErrNoTranscript
179		}
180	
181		return []byte(content), nil
182	}
183	
184	// ReadSessionMetadataAndPrompts reads a session's metadata and prompts from the
185	// v2 /main ref without requiring the raw transcript from /full/* refs.
186	// Used by explain when the raw transcript is unavailable but compact transcript
187	// (transcript.jsonl) on /main can substitute for display.
188	// Returns ErrCheckpointNotFound if the checkpoint or session doesn't exist on /main.
189	func (s *V2GitStore) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
190		if err := ctx.Err(); err != nil {
191			return nil, err //nolint:wrapcheck // Propagating context cancellation
192		}
193	
194		refName := plumbing.ReferenceName(paths.V2MainRefName)
195		_, rootTreeHash, err := s.GetRefState(refName)
196		if err != nil {
197			return nil, ErrCheckpointNotFound
198		}
199	
200		rootTree, err := s.repo.TreeObject(rootTreeHash)
201		if err != nil {
202			return nil, ErrCheckpointNotFound
203		}
204	
205		cpTree, err := rootTree.Tree(checkpointID.Path())
206		if err != nil {
207			return nil, ErrCheckpointNotFound
208		}
209	
210		sessionDir := strconv.Itoa(sessionIndex)
211		sessionTree, err := cpTree.Tree(sessionDir)
212		if err != nil {
213			return nil, ErrCheckpointNotFound
214		}
215	
216		result := &SessionContent{}
217	
218		if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
219			if content, contentErr := metadataFile.Contents(); contentErr == nil {
220				if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr != nil {
221					return nil, fmt.Errorf("failed to parse session metadata: %w", jsonErr)
222				}
223			}
224		}
225	
226		if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
227			if content, contentErr := file.Contents(); contentErr == nil {
228				result.Prompts = content
229			}
230		}
231	
232		// Read compact transcript from the same session tree (avoids a second tree walk).
233		if compactFile, fileErr := sessionTree.File(paths.CompactTranscriptFileName); fileErr == nil {
234			if content, contentErr := compactFile.Contents(); contentErr == nil && content != "" {
235				result.Transcript = []byte(content)
236			}
237		}
238	
239		return result, nil
240	}
241	
242	// ReadSessionContent reads a session's metadata and prompts from the v2 /main ref,
243	// and the raw transcript (full.jsonl) from /full/* refs (current + archived generations).
244	// This is the v2 equivalent of GitStore.ReadSessionContent — it reads the raw agent
245	// transcript, not the compact transcript.jsonl. Used by resume and RestoreLogsOnly.
246	// Returns ErrNoTranscript if the session exists but no raw transcript is available.
247	// Returns ErrCheckpointNotFound if the checkpoint or session doesn't exist on /main.
248	func (s *V2GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
249		if err := ctx.Err(); err != nil {
250			return nil, err //nolint:wrapcheck // Propagating context cancellation
251		}
252	
253		refName := plumbing.ReferenceName(paths.V2MainRefName)
254		_, rootTreeHash, err := s.GetRefState(refName)
255		if err != nil {
256			return nil, ErrCheckpointNotFound
257		}
258	
259		rootTree, err := s.repo.TreeObject(rootTreeHash)
260		if err != nil {
261			return nil, ErrCheckpointNotFound
262		}
263	
264		cpTree, err := rootTree.Tree(checkpointID.Path())
265		if err != nil {
266			return nil, ErrCheckpointNotFound
267		}
268	
269		sessionDir := strconv.Itoa(sessionIndex)
270		sessionTree, err := cpTree.Tree(sessionDir)
271		if err != nil {
272			return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
273		}
274	
275		result := &SessionContent{}
276	
277		if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
278			if content, contentErr := metadataFile.Contents(); contentErr == nil {
279				if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr != nil {
280					return nil, fmt.Errorf("failed to parse session metadata: %w", jsonErr)
281				}
282			}
283		}
284	
285		if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
286			if content, contentErr := file.Contents(); contentErr == nil {
287				result.Prompts = content
288			}
289		}
290	
291		transcript, transcriptErr := s.readTranscriptFromFullRefs(ctx, checkpointID, sessionIndex, result.Metadata.Agent)
292		if transcriptErr != nil {
293			return nil, fmt.Errorf("failed to read transcript from /full/* refs: %w", transcriptErr)
294		}
295		if len(transcript) == 0 {
296			return nil, ErrNoTranscript
297		}
298		result.Transcript = transcript
299	
300		return result, nil
301	}
302	
303	// readTranscriptFromFullRefs reads the raw transcript for a checkpoint session
304	// by searching /full/current first, then archived generations in reverse order.
305	// If not found locally, attempts to discover and fetch remote /full/* refs.
306	func (s *V2GitStore) readTranscriptFromFullRefs(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int, agentType types.AgentType) ([]byte, error) {
307		if err := ctx.Err(); err != nil {
308			return nil, err //nolint:wrapcheck // Propagating context cancellation
309		}
310	
311		sessionPath := fmt.Sprintf("%s/%d", checkpointID.Path(), sessionIndex)
312	
313		// Search locally first
314		transcript, err := s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath, agentType)
315		if err == nil && len(transcript) > 0 {
316			return transcript, nil
317		}
318	
319		archived, err := s.ListArchivedGenerations()
320		if err != nil {
321			return nil, err
322		}
323		for i := len(archived) - 1; i >= 0; i-- {
324			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + archived[i])
325			transcript, err := s.readTranscriptFromRef(refName, sessionPath, agentType)
326			if err == nil && len(transcript) > 0 {
327				return transcript, nil
328			}
329		}
330	
331		// Not found locally — try fetching remote /full/* refs
332		if fetchErr := s.fetchRemoteFullRefs(ctx); fetchErr != nil {
333			logging.Debug(ctx, "failed to fetch remote /full/* refs",
334				slog.String("error", fetchErr.Error()),
335			)
336			return nil, nil
337		}
338	
339		// Search newly fetched refs only
340		newArchived, err := s.ListArchivedGenerations()
341		if err != nil {
342			return nil, nil //nolint:nilerr // Best-effort: fetch-on-demand failure shouldn't block resume
343		}
344		existingSet := make(map[string]bool, len(archived))
345		for _, a := range archived {
346			existingSet[a] = true
347		}
348		for i := len(newArchived) - 1; i >= 0; i-- {
349			if existingSet[newArchived[i]] {
350				continue
351			}
352			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + newArchived[i])
353			transcript, err := s.readTranscriptFromRef(refName, sessionPath, agentType)
354			if err == nil && len(transcript) > 0 {
355				return transcript, nil
356			}
357		}
358	
359		// Also retry /full/current in case it was updated by the fetch
360		transcript, err = s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath, agentType)
361		if err == nil && len(transcript) > 0 {
362			return transcript, nil
363		}
364	
365		return nil, nil
366	}
367	
368	// fetchRemoteFullRefs discovers and fetches /full/* refs from the configured
369	// FetchRemote that aren't local.
370	func (s *V2GitStore) fetchRemoteFullRefs(ctx context.Context) error {
371		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
372		defer cancel()
373	
374		lsCmd := exec.CommandContext(ctx, "git", "ls-remote", s.FetchRemote, paths.V2FullRefPrefix+"*")
375		output, err := lsCmd.Output()
376		if err != nil {
377			return fmt.Errorf("ls-remote failed: %w", err)
378		}
379	
380		var refSpecs []string
381		for _, line := range strings.Split(strings.TrimSpace(string(output)), "\n") {
382			if line == "" {
383				continue
384			}
385			parts := strings.Fields(line)
386			if len(parts) < 2 {
387				continue
388			}
389			remoteRefName := parts[1]
390	
391			// Skip refs that already exist locally
392			if _, refErr := s.repo.Reference(plumbing.ReferenceName(remoteRefName), true); refErr == nil {
393				continue
394			}
395	
396			refSpecs = append(refSpecs, fmt.Sprintf("+%s:%s", remoteRefName, remoteRefName))
397		}
398	
399		if len(refSpecs) == 0 {
400			return nil
401		}
402	
403		args := append([]string{"fetch", "--no-tags", s.FetchRemote}, refSpecs...)
404		fetchCmd := exec.CommandContext(ctx, "git", args...)
405		if fetchOutput, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
406			return fmt.Errorf("fetch failed: %s", fetchOutput)
407		}
408	
409		return nil
410	}
411	
412	// readTranscriptFromRef reads the raw transcript from a specific /full/* ref.
413	// Follows the same chunking convention as readTranscriptFromTree in committed.go:
414	// chunk 0 is the base file (full.jsonl), chunks 1+ are full.jsonl.001, .002, etc.
415	// When chunk files exist, all chunks (including chunk 0) are reassembled using
416	// agent-aware reassembly via agent.ReassembleTranscript.
417	func (s *V2GitStore) readTranscriptFromRef(refName plumbing.ReferenceName, sessionPath string, agentType types.AgentType) ([]byte, error) {
418		_, rootTreeHash, err := s.GetRefState(refName)
419		if err != nil {
420			return nil, err
421		}
422	
423		rootTree, err := s.repo.TreeObject(rootTreeHash)
424		if err != nil {
425			return nil, fmt.Errorf("failed to read tree: %w", err)
426		}
427	
428		sessionTree, err := rootTree.Tree(sessionPath)
429		if err != nil {
430			return nil, fmt.Errorf("session path %s not found: %w", sessionPath, err)
431		}
432	
433		return readTranscriptFromObjectTree(sessionTree, agentType)
434	}
435	
436	// readTranscriptFromObjectTree reads and reassembles a transcript from a git tree object.
437	// Handles both chunked and non-chunked transcripts. Uses agent-aware reassembly
438	// when agentType is known, falling back to JSONL reassembly otherwise.
439	func readTranscriptFromObjectTree(tree *object.Tree, agentType types.AgentType) ([]byte, error) {
440		var chunkFiles []string
441		var hasBaseFile bool
442	
443		for _, entry := range tree.Entries {
444			if entry.Name == paths.TranscriptFileName {
445				hasBaseFile = true
446			}
447			if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
448				idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
449				if idx > 0 {
450					chunkFiles = append(chunkFiles, entry.Name)
451				}
452			}
453		}
454	
455		// If chunk files exist, reassemble all chunks (base file is chunk 0)
456		if len(chunkFiles) > 0 {
457			chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
458			if hasBaseFile {
459				chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
460			}
461	
462			var chunks [][]byte
463			for _, chunkFile := range chunkFiles {
464				file, fileErr := tree.File(chunkFile)
465				if fileErr != nil {
466					continue
467				}
468				content, contentErr := file.Contents()
469				if contentErr != nil {
470					continue
471				}
472				chunks = append(chunks, []byte(content))
473			}
474	
475			if len(chunks) > 0 {
476				result, reassembleErr := agent.ReassembleTranscript(chunks, agentType)
477				if reassembleErr != nil {
478					return nil, fmt.Errorf("failed to reassemble transcript: %w", reassembleErr)
479				}
480				return result, nil
481			}
482		}
483	
484		// No chunk files — read base file directly (non-chunked transcript)
485		if hasBaseFile {
486			file, err := tree.File(paths.TranscriptFileName)
487			if err == nil {
488				content, contentErr := file.Contents()
489				if contentErr == nil {
490					return []byte(content), nil
491				}
492			}
493		}
494	
495		return nil, nil
496	}
497	
498	// GetSessionLog reads the latest session's raw transcript and session ID from v2 refs.
499	// Convenience wrapper matching the GitStore.GetSessionLog signature.
500	func (s *V2GitStore) GetSessionLog(ctx context.Context, cpID id.CheckpointID) ([]byte, string, error) {
501		summary, err := s.ReadCommitted(ctx, cpID)
502		if err != nil {
503			return nil, "", err
504		}
505		if summary == nil {
506			return nil, "", ErrCheckpointNotFound
507		}
508		if len(summary.Sessions) == 0 {
509			return nil, "", ErrCheckpointNotFound
510		}
511	
512		latestIndex := len(summary.Sessions) - 1
513		content, err := s.ReadSessionContent(ctx, cpID, latestIndex)
514		if err != nil {
515			return nil, "", err
516		}
517		return content.Transcript, content.Metadata.SessionID, nil
518	}
519

