package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"time"

	"github.com/charmbracelet/huh"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/strategy"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/spf13/cobra"
)

func newDoctorCmd() *cobra.Command {
	var forceFlag bool

	cmd := &cobra.Command{
		Use:   "doctor",
		Short: "Diagnose and fix session issues",
		Long: `Scan for session issues and offer to fix them.

Checks performed:
  1. Disconnected metadata branches: detects when local and remote
     entire/checkpoints/v1 branches share no common ancestor (caused by a
     previous bug). Fixes by cherry-picking local checkpoints onto remote tip.
  2. Stuck sessions: sessions stuck in ACTIVE or ENDED phase that need cleanup.

A session is considered stuck if:
  - It is in ACTIVE phase with no interaction for over 1 hour
  - It is in ENDED phase with uncondensed checkpoint data on a shadow branch

For each stuck session, you can choose to:
  - Condense: Save session data to permanent storage (entire/checkpoints/v1 branch)
  - Discard: Remove the session state and shadow branch data
  - Skip: Leave the session as-is

Use --force to condense all fixable sessions without prompting.  Sessions that can't
be condensed will be discarded.`,
		PreRun: func(_ *cobra.Command, _ []string) {
			strategy.EnsureRedactionConfigured()
		},
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runSessionsFix(cmd, forceFlag)
		},
	}

	cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Auto-fix all issues without prompting")

	return cmd
}

// stuckSession holds a session state along with diagnostic info.
type stuckSession struct {
	State             *strategy.SessionState
	Reason            string
	ShadowBranch      string
	HasShadowBranch   bool
	CheckpointCount   int
	FilesTouchedCount int
}

func runSessionsFix(cmd *cobra.Command, force bool) error {
	var finalErr error

	// Check 1: Disconnected metadata branches
	metadataErr := checkDisconnectedMetadata(cmd, force)
	if metadataErr != nil {
		fmt.Fprintf(cmd.ErrOrStderr(), "Error: metadata check failed: %v\n", metadataErr)
		finalErr = NewSilentError(fmt.Errorf("metadata check failed: %w", metadataErr))
	}
	fmt.Fprintln(cmd.OutOrStdout())

	// Check 2: Stuck sessions
	ctx := cmd.Context()
	// Load all session states
	states, err := strategy.ListSessionStates(ctx)
	if err != nil {
		return fmt.Errorf("failed to list session states: %w", err)
	}

	if len(states) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
		if finalErr != nil {
			return finalErr
		}
		return nil
	}

	// Open repository to check shadow branches (uses worktree-aware helper)
	repo, err := openRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	// Identify stuck sessions
	now := time.Now()
	var stuck []stuckSession

	for _, state := range states {
		ss := classifySession(state, repo, now)
		if ss != nil {
			stuck = append(stuck, *ss)
		}
	}

	if len(stuck) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
		if finalErr != nil {
			return finalErr
		}
		return nil
	}

	// Get the current strategy for condense operations
	strat := GetStrategy(ctx)

	fmt.Fprintf(cmd.OutOrStdout(), "Found %d stuck session(s):\n\n", len(stuck))

	for _, ss := range stuck {
		displayStuckSession(cmd, ss)

		if force {
			if ss.HasShadowBranch && ss.CheckpointCount > 0 {
				if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
				} else {
					fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Condensed session %s\n\n", ss.State.SessionID)
				}
			} else {
				// Discard if we can't condense
				if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
				} else {
					fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Discarded session %s\n\n", ss.State.SessionID)
				}
			}
			continue
		}

		// Interactive: prompt for action
		action, err := promptSessionAction(ss)
		if err != nil {
			if errors.Is(err, huh.ErrUserAborted) {
				return nil
			}
			return fmt.Errorf("failed to get action: %w", err)
		}

		switch action {
		case "condense":
			if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
			} else {
				fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Condensed session %s\n\n", ss.State.SessionID)
			}
		case "discard":
			if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
			} else {
				fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Discarded session %s\n\n", ss.State.SessionID)
			}
		case "skip":
			fmt.Fprintf(cmd.OutOrStdout(), "  -> Skipped\n\n")
		}
	}

	if finalErr != nil {
		return finalErr
	}

	return nil
}

// classifySession determines if a session is stuck and returns diagnostic info.
// Returns nil if the session is healthy.
func classifySession(state *strategy.SessionState, repo *git.Repository, now time.Time) *stuckSession {
	// Determine shadow branch info
	shadowBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
	refName := plumbing.NewBranchReferenceName(shadowBranch)
	_, refErr := repo.Reference(refName, true)
	hasShadowBranch := refErr == nil

	switch {
	case state.Phase.IsActive():
		if !state.IsStuckActive() {
			return nil
		}

		var reason string
		if state.LastInteractionTime != nil {
			reason = fmt.Sprintf("active, last interaction %s ago", now.Sub(*state.LastInteractionTime).Truncate(time.Minute))
		} else {
			reason = fmt.Sprintf("active, started %s ago with no recorded interaction", now.Sub(state.StartedAt).Truncate(time.Minute))
		}

		return &stuckSession{
			State:             state,
			Reason:            reason,
			ShadowBranch:      shadowBranch,
			HasShadowBranch:   hasShadowBranch,
			CheckpointCount:   state.StepCount,
			FilesTouchedCount: len(state.FilesTouched),
		}

	case state.Phase == session.PhaseEnded:
		// Ended sessions are stuck if they have uncondensed data
		if state.StepCount <= 0 || !hasShadowBranch {
			return nil
		}

		return &stuckSession{
			State:             state,
			Reason:            "ended with uncondensed checkpoint data",
			ShadowBranch:      shadowBranch,
			HasShadowBranch:   hasShadowBranch,
			CheckpointCount:   state.StepCount,
			FilesTouchedCount: len(state.FilesTouched),
		}

	default:
		return nil
	}
}

// displayStuckSession prints diagnostic info for a stuck session.
func displayStuckSession(cmd *cobra.Command, ss stuckSession) {
	w := cmd.OutOrStdout()

	fmt.Fprintf(w, "  Session: %s\n", ss.State.SessionID)
	fmt.Fprintf(w, "  Phase:   %s\n", ss.State.Phase)
	fmt.Fprintf(w, "  Reason:  %s\n", ss.Reason)

	if ss.State.AgentType != "" {
		fmt.Fprintf(w, "  Agent:   %s\n", ss.State.AgentType)
	}

	if ss.State.LastInteractionTime != nil {
		fmt.Fprintf(w, "  Last interaction: %s\n", ss.State.LastInteractionTime.Format(time.RFC3339))
	}

	shadowStatus := "not found"
	if ss.HasShadowBranch {
		shadowStatus = fmt.Sprintf("exists (%s)", ss.ShadowBranch)
	}
	fmt.Fprintf(w, "  Shadow branch: %s\n", shadowStatus)
	fmt.Fprintf(w, "  Checkpoints: %d, Files touched: %d\n", ss.CheckpointCount, ss.FilesTouchedCount)
}

// promptSessionAction asks the user what to do with a stuck session.
func promptSessionAction(ss stuckSession) (string, error) {
	var action string

	options := make([]huh.Option[string], 0, 3)
	if ss.HasShadowBranch && ss.CheckpointCount > 0 {
		options = append(options, huh.NewOption("Condense (save to permanent storage)", "condense"))
	}
	options = append(options,
		huh.NewOption("Discard (remove session data)", "discard"),
		huh.NewOption("Skip (leave as-is)", "skip"),
	)

	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[string]().
				Title(fmt.Sprintf("Fix session %s?", ss.State.SessionID)).
				Options(options...).
				Value(&action),
		),
	)

	if err := form.Run(); err != nil {
		return "", fmt.Errorf("session fix prompt failed: %w", err)
	}

	return action, nil
}

// discardSession removes session state and cleans up the shadow branch.
func discardSession(ctx context.Context, ss stuckSession, _ *git.Repository, errW io.Writer) error {
	// Clear session state file
	if err := strategy.ClearSessionState(ctx, ss.State.SessionID); err != nil {
		return fmt.Errorf("failed to clear session state: %w", err)
	}

	// Delete shadow branch if it exists and no other sessions need it
	if ss.HasShadowBranch {
		if shouldDelete, err := canDeleteShadowBranch(ctx, ss.ShadowBranch, ss.State.SessionID); err != nil {
			fmt.Fprintf(errW, "Warning: could not check other sessions for shadow branch: %v\n", err)
		} else if shouldDelete {
			if err := strategy.DeleteBranchCLI(ctx, ss.ShadowBranch); err != nil {
				// Branch already gone is not an error — keeps discard idempotent
				if !errors.Is(err, strategy.ErrBranchNotFound) {
					return fmt.Errorf("failed to delete shadow branch: %w", err)
				}
			}
		}
	}

	return nil
}

// checkDisconnectedMetadata detects and optionally repairs disconnected
// local/remote metadata branches (the "empty-orphan bug").
func checkDisconnectedMetadata(cmd *cobra.Command, force bool) error {
	repo, err := openRepository(cmd.Context())
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	ctx := cmd.Context()
	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
	disconnected, err := strategy.IsMetadataDisconnected(ctx, repo, remoteRefName)
	if err != nil {
		return fmt.Errorf("could not check metadata branch state: %w", err)
	}

	w := cmd.OutOrStdout()

	if !disconnected {
		fmt.Fprintln(w, "✓ Metadata branches: OK")
		return nil
	}

	fmt.Fprintln(w, "Metadata branches: DISCONNECTED")
	fmt.Fprintln(w, "  Local and remote entire/checkpoints/v1 branches share no common ancestor.")
	fmt.Fprintln(w, "  Some remote checkpoints may not be visible locally.")
	fmt.Fprintln(w, "  Fix: cherry-pick local checkpoints onto remote tip (preserves all data).")

	if !force {
		var confirmed bool
		form := NewAccessibleForm(
			huh.NewGroup(
				huh.NewConfirm().
					Title("Fix disconnected metadata branches?").
					Value(&confirmed),
			),
		)
		if formErr := form.Run(); formErr != nil {
			if errors.Is(formErr, huh.ErrUserAborted) {
				return nil
			}
			return fmt.Errorf("prompt failed: %w", formErr)
		}
		if !confirmed {
			fmt.Fprintln(w, "  -> Skipped")
			return nil
		}
	}

	if fixErr := strategy.ReconcileDisconnectedMetadataBranch(ctx, repo, remoteRefName, cmd.ErrOrStderr()); fixErr != nil {
		return fmt.Errorf("failed to reconcile metadata branches: %w", fixErr)
	}

	fmt.Fprintln(w, "  ✓ Fixed: metadata branches reconciled")
	return nil
}

// checkV2RefExistence verifies that v2 refs exist (or both are absent for a fresh repo).
// One ref without the other suggests a partial initialization.
func checkV2RefExistence(cmd *cobra.Command, repo *git.Repository) error {
	w := cmd.OutOrStdout()

	mainRefName := plumbing.ReferenceName(paths.V2MainRefName)
	fullRefName := plumbing.ReferenceName(paths.V2FullCurrentRefName)

	_, mainErr := repo.Reference(mainRefName, true)
	_, fullErr := repo.Reference(fullRefName, true)

	hasMain := mainErr == nil
	hasFull := fullErr == nil

	switch {
	case hasMain && hasFull:
		fmt.Fprintln(w, "✓ v2 refs: OK")
	case !hasMain && !hasFull:
		fmt.Fprintln(w, "✓ v2 refs: OK (no checkpoints written yet)")
	case hasMain && !hasFull:
		fmt.Fprintln(w, "v2 refs: INCONSISTENT — /main exists but /full/current is missing")
	case !hasMain && hasFull:
		fmt.Fprintln(w, "v2 refs: INCONSISTENT — /full/current exists but /main is missing")
	}

	return nil
}

// canDeleteShadowBranch checks if a shadow branch can be safely deleted.
// Returns true if no other sessions (besides excludeSessionID) need this branch.
func canDeleteShadowBranch(ctx context.Context, shadowBranch, excludeSessionID string) (bool, error) {
	states, err := strategy.ListSessionStates(ctx)
	if err != nil {
		return false, fmt.Errorf("failed to list session states: %w", err)
	}

	for _, state := range states {
		if state.SessionID == excludeSessionID {
			continue
		}
		otherShadow := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
		if otherShadow == shadowBranch && state.StepCount > 0 {
			return false, nil
		}
	}

	return true, nil
}

package checkpoint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// DefaultMaxCheckpointsPerGeneration is the rotation threshold.
// When a generation reaches this many checkpoints, it is archived
// and a fresh /full/current is created.
const DefaultMaxCheckpointsPerGeneration = 100

// GenerationMetadata tracks the state of a /full/* generation.
// Written to the tree root as generation.json at archive time only — not during
// normal writes to /full/current. This keeps /full/current free of root-level
// files, ensuring conflict-free tree merges during push recovery.
//
// The generation's sequence number is derived from the ref name, not stored here.
// Checkpoint membership is determined by walking the tree (shard directories).
type GenerationMetadata struct {
	// OldestCheckpointAt is the creation time of the earliest checkpoint.
	OldestCheckpointAt time.Time `json:"oldest_checkpoint_at"`

	// NewestCheckpointAt is the creation time of the most recent checkpoint.
	NewestCheckpointAt time.Time `json:"newest_checkpoint_at"`
}

// readGeneration reads generation.json from the given tree hash.
// Returns a zero-value GenerationMetadata if the file doesn't exist (new/empty generation).
func (s *V2GitStore) readGeneration(treeHash plumbing.Hash) (GenerationMetadata, error) {
	if treeHash == plumbing.ZeroHash {
		return GenerationMetadata{}, nil
	}

	tree, err := s.repo.TreeObject(treeHash)
	if err != nil {
		return GenerationMetadata{}, fmt.Errorf("failed to read tree: %w", err)
	}

	file, err := tree.File(paths.GenerationFileName)
	if err != nil {
		if errors.Is(err, object.ErrFileNotFound) || errors.Is(err, object.ErrEntryNotFound) {
			return GenerationMetadata{}, nil
		}
		return GenerationMetadata{}, fmt.Errorf("failed to find %s in tree: %w", paths.GenerationFileName, err)
	}

	content, err := file.Contents()
	if err != nil {
		return GenerationMetadata{}, fmt.Errorf("failed to read %s: %w", paths.GenerationFileName, err)
	}

	var gen GenerationMetadata
	if err := json.Unmarshal([]byte(content), &gen); err != nil {
		return GenerationMetadata{}, fmt.Errorf("failed to parse %s: %w", paths.GenerationFileName, err)
	}

	return gen, nil
}

// readGenerationFromRef reads generation.json from the tree pointed to by the given ref.
func (s *V2GitStore) readGenerationFromRef(refName plumbing.ReferenceName) (GenerationMetadata, error) {
	_, treeHash, err := s.GetRefState(refName)
	if err != nil {
		return GenerationMetadata{}, fmt.Errorf("failed to get ref state: %w", err)
	}
	return s.readGeneration(treeHash)
}

// marshalGenerationBlob marshals gen as generation.json and stores it as a git blob.
// Returns a TreeEntry ready to be placed in a tree.
func (s *V2GitStore) marshalGenerationBlob(gen GenerationMetadata) (object.TreeEntry, error) {
	data, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to marshal %s: %w", paths.GenerationFileName, err)
	}

	blobHash, err := CreateBlobFromContent(s.repo, data)
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to create %s blob: %w", paths.GenerationFileName, err)
	}

	return object.TreeEntry{
		Name: paths.GenerationFileName,
		Mode: filemode.Regular,
		Hash: blobHash,
	}, nil
}

// writeGeneration marshals gen as generation.json and adds the blob entry to entries.
func (s *V2GitStore) writeGeneration(gen GenerationMetadata, entries map[string]object.TreeEntry) error {
	entry, err := s.marshalGenerationBlob(gen)
	if err != nil {
		return err
	}
	entries[paths.GenerationFileName] = entry
	return nil
}

// CountCheckpointsInTree counts checkpoint shard directories in a /full/* tree.
// The tree structure is <id[:2]>/<id[2:]>/ — we count second-level directories
// across all shard prefixes. Returns 0 for an empty tree.
func (s *V2GitStore) CountCheckpointsInTree(treeHash plumbing.Hash) (int, error) {
	if treeHash == plumbing.ZeroHash {
		return 0, nil
	}

	tree, err := s.repo.TreeObject(treeHash)
	if err != nil {
		return 0, fmt.Errorf("failed to read tree: %w", err)
	}

	count := 0
	if err := WalkCheckpointShards(s.repo, tree, func(_ id.CheckpointID, _ plumbing.Hash) error {
		count++
		return nil
	}); err != nil {
		return 0, err
	}

	return count, nil
}

// AddGenerationJSONToTree adds generation.json to an existing root tree, returning
// a new root tree hash. Preserves all existing entries (shard directories, etc.).
func (s *V2GitStore) AddGenerationJSONToTree(rootTreeHash plumbing.Hash, gen GenerationMetadata) (plumbing.Hash, error) {
	entry, err := s.marshalGenerationBlob(gen)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	return UpdateSubtree(s.repo, rootTreeHash, nil, []object.TreeEntry{entry},
		UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
}

// computeGenerationTimestamps derives timestamps for a generation being archived.
// Uses the commit history of the /full/current ref: oldest = first commit time,
// newest = latest commit time. Falls back to time.Now() if the ref has no history.
// Note: /full/* trees don't contain session metadata (that's on /main), so we
// derive timestamps from git commit times rather than walking the tree.
func (s *V2GitStore) computeGenerationTimestamps() GenerationMetadata {
	now := time.Now().UTC()
	fallback := GenerationMetadata{OldestCheckpointAt: now, NewestCheckpointAt: now}

	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return fallback
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return fallback
	}

	newest := commit.Committer.When.UTC()

	// Walk parents to find the oldest commit in this generation
	iter := commit
	for len(iter.ParentHashes) > 0 {
		parent, parentErr := s.repo.CommitObject(iter.ParentHashes[0])
		if parentErr != nil {
			break
		}
		iter = parent
	}
	oldest := iter.Committer.When.UTC()

	return GenerationMetadata{
		OldestCheckpointAt: oldest,
		NewestCheckpointAt: newest,
	}
}

// generationRefWidth is the zero-padded width of archived generation ref names.
const generationRefWidth = 13

// GenerationRefPattern matches exactly 13 digits (the archived generation ref suffix format).
var GenerationRefPattern = regexp.MustCompile(`^\d{13}$`)

// listArchivedGenerations returns the names of all archived generation refs
// (everything under V2FullRefPrefix matching the expected numeric format), sorted ascending.
func (s *V2GitStore) ListArchivedGenerations() ([]string, error) {
	refs, err := s.repo.References()
	if err != nil {
		return nil, fmt.Errorf("failed to list references: %w", err)
	}

	var archived []string
	err = refs.ForEach(func(ref *plumbing.Reference) error {
		name := ref.Name().String()
		if !strings.HasPrefix(name, paths.V2FullRefPrefix) {
			return nil
		}
		suffix := strings.TrimPrefix(name, paths.V2FullRefPrefix)
		if suffix == "current" || !GenerationRefPattern.MatchString(suffix) {
			return nil
		}
		archived = append(archived, suffix)
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to iterate references: %w", err)
	}

	sort.Strings(archived)
	return archived, nil
}

// nextGenerationNumber returns the next sequential generation number for archiving.
// Scans existing archived refs and returns max+1. Returns 1 if no archives exist.
func (s *V2GitStore) nextGenerationNumber() (int, error) {
	archived, err := s.ListArchivedGenerations()
	if err != nil {
		return 0, err
	}

	var maxNum int64
	for _, name := range archived {
		n, parseErr := strconv.ParseInt(name, 10, 64)
		if parseErr != nil {
			continue // skip unparseable entries
		}
		if n > maxNum {
			maxNum = n
		}
	}
	return int(maxNum) + 1, nil
}

// rotateGeneration archives the current /full/current generation and creates
// a fresh orphan. This is a 2-phase operation:
//
//  1. Archive: determine the next generation number, create a new ref pointing
//     to the current /full/current commit.
//  2. Reset: create a fresh orphan commit with an empty tree + seed generation.json,
//     point /full/current at it.
func (s *V2GitStore) rotateGeneration(ctx context.Context) error {
	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)

	// Guard against concurrent rotation: re-read /full/current and check if
	// it's still above the threshold. If not, another instance already rotated.
	_, currentTreeHash, err := s.GetRefState(refName)
	if err != nil {
		return fmt.Errorf("rotation: failed to read /full/current: %w", err)
	}
	checkpointCount, err := s.CountCheckpointsInTree(currentTreeHash)
	if err != nil {
		return fmt.Errorf("rotation: failed to count checkpoints: %w", err)
	}
	if checkpointCount < s.maxCheckpoints() {
		return nil
	}

	currentRef, err := s.repo.Reference(refName, true)
	if err != nil {
		return fmt.Errorf("rotation: failed to read /full/current ref: %w", err)
	}

	archiveNumber, err := s.nextGenerationNumber()
	if err != nil {
		return fmt.Errorf("rotation: failed to determine next generation number: %w", err)
	}

	// Phase 1: Archive — create ref pointing to the current commit.
	// If the archive ref already exists, another instance already rotated — skip.
	archiveRefName := plumbing.ReferenceName(fmt.Sprintf("%s%0*d", paths.V2FullRefPrefix, generationRefWidth, archiveNumber))
	if _, refErr := s.repo.Reference(archiveRefName, true); refErr == nil {
		logging.Info(ctx, "rotation: archive ref already exists, skipping",
			slog.String("archive_ref", string(archiveRefName)),
		)
		return nil
	}
	archiveRef := plumbing.NewHashReference(archiveRefName, currentRef.Hash())
	if err := s.repo.Storer.SetReference(archiveRef); err != nil {
		return fmt.Errorf("rotation: failed to create archived ref %s: %w", archiveRefName, err)
	}

	// Verify /full/current hasn't been advanced by another writer since we read it.
	// If it changed, abort — the archive ref is harmless (points to a valid commit)
	// and the next writer will trigger rotation again.
	postArchiveRef, err := s.repo.Reference(refName, true)
	if err != nil {
		return fmt.Errorf("rotation: failed to re-read /full/current: %w", err)
	}
	if postArchiveRef.Hash() != currentRef.Hash() {
		logging.Info(ctx, "rotation: /full/current changed during rotation, aborting reset")
		return nil
	}

	// Write generation.json to the current tree before archiving.
	gen := s.computeGenerationTimestamps()
	archiveTreeHash, err := s.AddGenerationJSONToTree(currentTreeHash, gen)
	if err != nil {
		return fmt.Errorf("rotation: failed to add generation.json: %w", err)
	}

	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
	archiveCommitHash, err := CreateCommit(s.repo, archiveTreeHash, currentRef.Hash(), "Archive generation", authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("rotation: failed to create archive commit: %w", err)
	}

	// Update the archive ref to point to the commit with generation.json
	archiveRef = plumbing.NewHashReference(archiveRefName, archiveCommitHash)
	if err := s.repo.Storer.SetReference(archiveRef); err != nil {
		return fmt.Errorf("rotation: failed to update archived ref %s: %w", archiveRefName, err)
	}

	// Phase 2: Create fresh orphan /full/current (empty tree, no generation.json)
	emptyTreeHash, err := BuildTreeFromEntries(ctx, s.repo, make(map[string]object.TreeEntry))
	if err != nil {
		return fmt.Errorf("rotation: failed to build empty tree: %w", err)
	}

	orphanCommitHash, err := CreateCommit(s.repo, emptyTreeHash, plumbing.ZeroHash, "Start generation", authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("rotation: failed to create orphan commit: %w", err)
	}

	orphanRef := plumbing.NewHashReference(refName, orphanCommitHash)
	if err := s.repo.Storer.SetReference(orphanRef); err != nil {
		return fmt.Errorf("rotation: failed to reset /full/current: %w", err)
	}

	logging.Info(ctx, "generation rotation complete",
		slog.Int("archived_generation", archiveNumber),
		slog.String("archive_ref", string(archiveRefName)),
	)

	return nil
}

