	// Create orphan metadata branch
	run("checkout", "--orphan", paths.MetadataBranchName)
	run("rm", "-rf", ".")
	if err := os.WriteFile(filepath.Join(tmpDir, "metadata.json"), []byte(`{"test":true}`), 0o644); err != nil {
